from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        MAX_VAL = 300
        MAX_DIFF = 300  # possible diffs are 0..299

        # best[v][d] = longest valid subsequence ending with value v
        # whose last adjacent difference is at least d.
        best = [[0] * MAX_DIFF for _ in range(MAX_VAL + 1)]
        ans = 1

        for x in nums:
            add = [0] * MAX_DIFF

            for y in range(1, MAX_VAL + 1):
                d = abs(x - y)
                prev = best[y][d]
                if prev:
                    cand = prev + 1
                    if cand > add[d]:
                        add[d] = cand

            row = best[x]
            suffix = 0
            for d in range(MAX_DIFF - 1, -1, -1):
                if add[d] > suffix:
                    suffix = add[d]
                val = suffix if suffix > 1 else 1
                if val > row[d]:
                    row[d] = val

            if row[0] > ans:
                ans = row[0]

        return ans
